# mpscring.map — the functions libmpscring.so exports, under the version node MPSCRING_<major> (the soname major): exactly the
# functions app/mpscring.h declares (the `function` lines of abi/layout.txt; utils/check_abi.sh --exports refuses any difference).
# Everything else stays local. The .a archive is unaffected.
MPSCRING_1 {
  global:
    mpsc_ring_capacity;
    mpsc_ring_destroy;
    mpsc_ring_init;
    mpsc_ring_init_into;
    mpsc_ring_is_empty;
    mpsc_ring_pop;
    mpsc_ring_push;
    mpsc_ring_storage_size;
  local:
    *;
};
